/**
 * @fileoverview Test the usage of deprecated methods
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-method-call'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0',
            toVersion: '7.9.0'
        }
    }
});
ruleTester.run('no-deprecated-method-call', rule, {

    valid: [
        {
            code: `
                Ext.Array.clean(['a', null, '', 'b']);
                Ext.Array.max([1, 5, 3]);
            `
        }
    ],

    invalid: [
        {
            code: `
                Ext.create('Ext.chart.MarkerHolder', {}).getBoundMarker();
            `,
            errors: [
                { message: /Call to deprecated method 'getBoundMarker' found for 'Ext.chart.MarkerHolder'.*/ }
            ]
        },
        {
            code: `
                Ext.clean(['a', null, '', 'b']);
                Ext.max([1, 5, 3]);
            `,
            output: `
                Ext.Array.clean(['a', null, '', 'b']);
                Ext.Array.max([1, 5, 3]);
            `,
            errors: [
                { message: /Call to deprecated method 'clean' found for 'Ext'.*/ },
                { message: /Call to deprecated method 'max' found for 'Ext'.*/ }
            ]
        },
        {
            code: `
                // testing deprecated 'createWidget' method
                Ext.createWidget('window', {});

                // testing deprecated 'clearInvalid' method
                Ext.create('field', {}).clearInvalid();

                // testing deprecated 'clearInvalid' method from a chained Ext.create() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'inputfield';
                        Ext.create(type, {}).clearInvalid();
                    }
                });

                // testing deprecated 'clearInvalid' method from a chained Ext.widget() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'containerfield';
                        Ext.widget(type, {}).clearInvalid();
                    }
                });

                // testing deprecated 'clearInvalid' method from a chained Ext.create() call that uses a variable for the className
                Ext.define('MyClass', {
                    constructor: function () {
                        var className = 'Ext.field.Display';
                        Ext.create(className, {}).clearInvalid();
                    }
                });

                // testing deprecated 'clearInvalid' method from a chained new xClass() call that uses a variable for the xClass
                Ext.define('MyClass', {
                    constructor: function () {
                        var xClass = Ext.field.Field;
                        new xClass().clearInvalid();
                    }
                });
            `,
            output: `
                // testing deprecated 'createWidget' method
                Ext.widget('window', {});

                // testing deprecated 'clearInvalid' method
                Ext.create('field', {}).clearInvalid();

                // testing deprecated 'clearInvalid' method from a chained Ext.create() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'inputfield';
                        Ext.create(type, {}).clearInvalid();
                    }
                });

                // testing deprecated 'clearInvalid' method from a chained Ext.widget() call that uses a variable for the xtype
                Ext.define('MyClass', {
                    constructor: function () {
                        var type = 'containerfield';
                        Ext.widget(type, {}).clearInvalid();
                    }
                });

                // testing deprecated 'clearInvalid' method from a chained Ext.create() call that uses a variable for the className
                Ext.define('MyClass', {
                    constructor: function () {
                        var className = 'Ext.field.Display';
                        Ext.create(className, {}).clearInvalid();
                    }
                });

                // testing deprecated 'clearInvalid' method from a chained new xClass() call that uses a variable for the xClass
                Ext.define('MyClass', {
                    constructor: function () {
                        var xClass = Ext.field.Field;
                        new xClass().clearInvalid();
                    }
                });
            `,
            errors: [
                { message: /Call to deprecated method 'createWidget' found for 'Ext'.*/ },
                { message: /Call to deprecated method 'clearInvalid' found for 'Ext.field.Field'.*/ },
                { message: /Call to deprecated method 'clearInvalid' found for 'Ext.field.Input'.*/ },
                { message: /Call to deprecated method 'clearInvalid' found for 'Ext.field.Container'.*/ },
                { message: /Call to deprecated method 'clearInvalid' found for 'Ext.field.Display'.*/ },
                { message: /Call to deprecated method 'clearInvalid' found for 'Ext.field.Field'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Panel',
                    someCustomMethod: function () {
                        this.resetFloating();
                    },
                    someCustomMethod: function () {
                        var me = this;
                        me.fromElement();
                    }
                });

                Ext.define('MyOverrideComponent', {
                    override: 'Ext.Sheet',
                    someCustomMethod: function () {
                        this.resetFloating();
                    },
                    someCustomMethod: function () {
                        var me = this;
                        me.fromElement();
                    }
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Panel',
                    someCustomMethod: function () {
                        this.resetPositioned();
                    },
                    someCustomMethod: function () {
                        var me = this;
                        me.fromElement();
                    }
                });

                Ext.define('MyOverrideComponent', {
                    override: 'Ext.Sheet',
                    someCustomMethod: function () {
                        this.resetPositioned();
                    },
                    someCustomMethod: function () {
                        var me = this;
                        me.fromElement();
                    }
                });
            `,
            errors: [
                { message: /Call to deprecated method 'resetFloating' found for 'Ext.Panel'.*/ },
                { message: /Call to deprecated method 'fromElement' found for 'Ext.Panel'.*/ },
                { message: /Call to deprecated method 'resetFloating' found for 'Ext.Sheet'.*/ },
                { message: /Call to deprecated method 'fromElement' found for 'Ext.Sheet'.*/ }
            ]
        },
        {
            code: `
                Ext.define('MyCustomDataView', {
                    extend: 'Ext.dataview.DataView',
                    customMethod: function (item) {
                        var idx = this.getItemIndex(item);
                    }
                });
            `,
            output: `
                Ext.define('MyCustomDataView', {
                    extend: 'Ext.dataview.DataView',
                    customMethod: function (item) {
                        var idx = this.mapToViewIndex(item);
                    }
                });
            `,
            errors: [
                { message: /Call to deprecated method 'getItemIndex' found for 'Ext.dataview.DataView'.*/ }
            ]
        }
    ]
});
